// A sitemap is one of two documents and they look nearly identical.
//
// docs.n8n.io and developer.mozilla.org both answer /sitemap.xml with a
// <sitemapindex> whose <loc> entries are nine and eleven *other sitemaps*.
// Measured 2026-08-31. Fetching those as if they were pages indexes XML, and
// the index then answers customer questions with fragments of a sitemap.
//
// single-item input: one sitemap was fetched.
const cfg = $('Indexing Settings').first().json;

function bodyOf(x) {
  if (x == null) { return ''; }
  if (typeof x === 'string') { return x; }
  if (typeof x.data === 'string') { return x.data; }
  if (typeof x.body === 'string') { return x.body; }
  return JSON.stringify(x);
}

const xml = bodyOf($input.first().json);
if (xml.indexOf('<loc') < 0) {
  throw new Error('Nothing that looks like a sitemap came back from ' + cfg.docs_sitemap + '. A gzipped .xml.gz cannot be read here - point this at the plain XML.');
}

const isIndex = /<sitemapindex[\s>]/i.test(xml);
const locs = [...xml.matchAll(/<loc>\s*([^<\s]+)\s*<\/loc>/gi)].map(function (m) { return m[1]; });

// The cap on child sitemaps is deliberate: a large documentation site lists
// dozens of them, and every one is another fetch before a single page is read.
return locs.slice(0, isIndex ? 12 : 5000).map(function (u) {
  return { json: { kind: isIndex ? 'child' : 'page', url: u } };
});

// The second pass, one input item per child sitemap. Only reached when the
// first document turned out to be an index of sitemaps.
function bodyOf(x) {
  if (x == null) { return ''; }
  if (typeof x === 'string') { return x; }
  if (typeof x.data === 'string') { return x.data; }
  if (typeof x.body === 'string') { return x.body; }
  return JSON.stringify(x);
}

const out = [];
for (const item of $input.all()) {
  const xml = bodyOf(item.json);
  for (const m of xml.matchAll(/<loc>\s*([^<\s]+)\s*<\/loc>/gi)) {
    out.push({ json: { kind: 'page', url: m[1] } });
  }
}

// A step that can return nothing ends the branch, and the Merge below would
// then wait on an input that never arrives. One marker item always comes back;
// the filter in the next node drops it.
if (!out.length) { return [{ json: { kind: 'page', url: '' } }]; }
return out;

// Both shapes of sitemap land here, so this is the first place that sees the
// whole list of pages.
const cfg = $('Indexing Settings').first().json;
const must = String(cfg.url_must_contain || '').trim().toLowerCase();
const cap = Math.max(1, Number(cfg.max_pages) || 25);

const seen = new Set();
const out = [];
let looked = 0;

for (const item of $input.all()) {
  let u = String((item.json || {}).url || '').trim();
  if (!u || u.slice(0, 4) !== 'http') { continue; }
  looked++;
  u = u.split('#')[0];
  if (u.length > 10 && u.slice(-1) === '/') { u = u.slice(0, -1); }
  if (/\.(png|jpe?g|gif|svg|webp|pdf|zip|css|js|xml|json)$/i.test(u)) { continue; }
  if (must && u.toLowerCase().indexOf(must) < 0) { continue; }
  if (seen.has(u)) { continue; }
  seen.add(u);
  out.push({ json: { url: u } });
  if (out.length >= cap) { break; }
}

if (!out.length) {
  throw new Error('The sitemap listed ' + looked + ' URLs and none of them contain "' + cfg.url_must_contain + '". Widen url_must_contain, or empty it to index everything.');
}
return out;

// HTML in, passages out.
//
// Narrowing to <article> or <main> first is doing real work rather than being
// tidy: a documentation page is mostly navigation, and a passage cut out of the
// sidebar is equally close to every question ever asked - so the sidebar
// becomes the answer to everything.
const cfg = $('Indexing Settings').first().json;
const size = Math.max(400, Number(cfg.chunk_chars) || 1200);
const overlap = Math.round(size * 0.15);
const dims = Number(cfg.dimensions) || 768;
const model = 'models/' + String(cfg.embedding_model || 'gemini-embedding-001');

function bodyOf(x) {
  if (x == null) { return ''; }
  if (typeof x === 'string') { return x; }
  if (typeof x.data === 'string') { return x.data; }
  if (typeof x.body === 'string') { return x.body; }
  return '';
}

function clean(html) {
  let t = html.replace(/<(script|style|nav|header|footer|svg|noscript|form|aside)\b[\s\S]*?<\/\1>/gi, ' ');
  const main = t.match(/<article\b[^>]*>([\s\S]*?)<\/article>/i) || t.match(/<main\b[^>]*>([\s\S]*?)<\/main>/i);
  t = main ? main[1] : t;
  t = t.replace(/<\/(p|div|li|h[1-6]|tr|section|pre)>/gi, '\n');
  t = t.replace(/<[^>]+>/g, ' ');
  t = t.replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<')
       .replace(/&gt;/gi, '>').replace(/&quot;/gi, '"');
  // Numeric entities in both spellings. The first indexing run left `&#x27;`
  // sitting in the stored passages: hex is what most static site generators
  // emit for an apostrophe, and a passage full of `&#x27;` is a passage the
  // model has to read around.
  t = t.replace(/&#x([0-9a-f]{1,6});/gi, function (m, h) { return String.fromCharCode(parseInt(h, 16)); });
  t = t.replace(/&#([0-9]{1,7});/g, function (m, d) { return String.fromCharCode(Number(d)); });
  return t.replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
}

function split(text) {
  const parts = [];
  let i = 0;
  while (i < text.length) {
    let end = Math.min(text.length, i + size);
    if (end < text.length) {
      const window = text.slice(i, end);
      const br = Math.max(window.lastIndexOf('\n\n'), window.lastIndexOf('. '));
      if (br > size * 0.5) { end = i + br + 1; }
    }
    const piece = text.slice(i, end).trim();
    if (piece.length > 80) { parts.push(piece); }
    if (end >= text.length) { break; }
    i = Math.max(i + 1, end - overlap);
    // Start the next passage on a word boundary. The first run stored one
    // beginning "s. All production workflows need..." - the overlap had cut
    // "trigger nodes" in half, and that fragment is what got retrieved.
    const space = text.indexOf(' ', i);
    if (space > i && space - i < 40) { i = space + 1; }
  }
  return parts.slice(0, 40);
}

const fetched = $input.all();
const asked = $('Pick The Pages Worth Indexing').all();
if (fetched.length !== asked.length) {
  throw new Error('Fetched ' + fetched.length + ' pages for ' + asked.length + ' URLs. The two lists are matched by position, so this run cannot be trusted.');
}

const out = [];
for (let p = 0; p < fetched.length; p++) {
  const html = bodyOf(fetched[p].json);
  const url = String(((asked[p] || {}).json || {}).url || '');
  const titled = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  const title = titled ? titled[1].replace(/\s+/g, ' ').trim().slice(0, 120) : url;
  const text = clean(html);
  // Under 200 characters of prose is a redirect stub or a page that renders its
  // content in the browser. Neither is worth an embedding call.
  if (text.length < 200) { continue; }
  const chunks = split(text);
  if (!chunks.length) { continue; }
  out.push({ json: {
    url: url,
    title: title,
    chunks: chunks,
    body: { requests: chunks.map(function (c) {
      return {
        model: model,
        content: { parts: [{ text: c }] },
        outputDimensionality: dims,
        taskType: 'RETRIEVAL_DOCUMENT',
      };
    }) },
  }});
}

if (!out.length) {
  throw new Error('None of the ' + fetched.length + ' pages held readable text. If the docs render in the browser rather than in the HTML, this cannot index them.');
}
return out;

// One row per passage, ready to store.
//
// gemini-embedding-001 returns a unit vector at its full 3072 dimensions and an
// unnormalised one at every smaller size. Measured 2026-08-31: the same
// sentence came back with |v| = 1.0000 at 3072 and 0.5839 at 768. So raw
// 768-vectors are not comparable by dot product - three passages scored 0.19,
// 0.25 and 0.19 raw where their cosines were 0.55, 0.74 and 0.56 - and a
// relevance floor set on those numbers rejects everything the docs contain.
// Normalising here means the query side can dot and be done.
const runId = String($execution.id);
const pages = $('Turn Each Page Into Passages').all();
const replies = $input.all();

if (pages.length !== replies.length) {
  throw new Error('Got ' + replies.length + ' embedding responses for ' + pages.length + ' pages.');
}

const rows = [];
for (let p = 0; p < pages.length; p++) {
  const page = pages[p].json;
  const payload = replies[p].json || {};
  if (payload.error) {
    throw new Error('The embeddings endpoint refused a page: ' + JSON.stringify(payload.error).slice(0, 300));
  }
  const vecs = payload.embeddings || [];
  if (vecs.length !== page.chunks.length) {
    throw new Error('Asked for ' + page.chunks.length + ' embeddings for ' + page.url + ' and got ' + vecs.length + '. The response is matched to the request by position.');
  }
  for (let c = 0; c < page.chunks.length; c++) {
    const v = (vecs[c] || {}).values || [];
    let n = 0;
    for (const x of v) { n += x * x; }
    n = Math.sqrt(n) || 1;
    const packed = v.map(function (x) { return (x / n).toFixed(4); }).join(',');
    rows.push({ json: {
      chunk_key: page.url + '#' + c,
      url: page.url,
      title: page.title,
      text: page.chunks[c],
      vec: packed,
      run_id: runId,
    }});
  }
}
return rows;

// What the rebuild left behind, so a run that indexed nothing says so rather
// than ending green and empty.
const rows = $('Normalise The Vectors').all();
const perPage = {};
for (const r of rows) {
  const u = r.json.url;
  perPage[u] = (perPage[u] || 0) + 1;
}
const urls = Object.keys(perPage);
return [{ json: {
  pages_indexed: urls.length,
  passages_written: rows.length,
  run_id: String($execution.id),
  sample: urls.slice(0, 5),
}}];

// The trigger runs with `simple` off, which is the only way to get a body at
// all: with it on, n8n asks Gmail for `format: metadata` and the item comes
// back holding a ~150 character `snippet`, no `text` and no top-level
// `subject`. Read out of GmailTrigger.node.js on 2.35.5 rather than assumed.
//
// single-item input: the trigger fires once per message.
const j = $('Watch The Support Label').first().json || {};

function fromAddress(f) {
  if (!f) { return ''; }
  if (typeof f === 'string') { return f; }
  if (f.value && f.value.length) { return String(f.value[0].address || ''); }
  return String(f.text || '');
}

let body = String(j.text || '');
if (!body.trim() && j.html) {
  body = String(j.html).replace(/<[^>]+>/g, ' ');
}

// Everything below the first quote marker belongs to an earlier message.
// Embedding it retrieves the docs for the whole thread at once, and the
// question the customer actually asked stops being the strongest signal in
// their own email.
const cut = body.search(/^\s*(On .{5,160}wrote:|-{2,}\s*Original Message|_{10,}|From:\s)/m);
if (cut > 40) { body = body.slice(0, cut); }
body = body.split(/\n-- \n/)[0];
body = body.split('\n').filter(function (l) { return l.trim().charAt(0) !== '>'; }).join('\n');

const question = body.replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim().slice(0, 4000);
const subject = String(j.subject || '(no subject)');

return [{ json: {
  // A one-line "see subject" email is common enough to handle: there, the
  // subject is the question.
  question: question.length > 15 ? question : subject,
  subject: subject,
  reply_to: fromAddress(j.from),
  thread_id: String(j.threadId || ''),
  asked_on: String(j.date || '').slice(0, 10),
}}];

// Cosine similarity against every stored passage, in code, over a Data Table.
//
// Both sides are unit vectors - the index was normalised when it was written,
// the question is normalised below - so the dot product is the cosine and
// nothing has to divide at query time.
//
// single-item input: one question per run.
const cfg = $('Answer Settings').first().json;
const topK = Math.max(1, Number(cfg.passages) || 5);
const floor = Number(cfg.min_score);
const asked = $('Read The Question').first().json;

const payload = $('Embed The Question').first().json || {};
if (payload.error) {
  throw new Error('The embeddings endpoint refused the question: ' + JSON.stringify(payload.error).slice(0, 300));
}
const raw = ((payload.embedding || {}).values) || [];
if (!raw.length) { throw new Error('No embedding came back for the question.'); }

let qn = 0;
for (const x of raw) { qn += x * x; }
qn = Math.sqrt(qn) || 1;
const q = raw.map(function (x) { return x / qn; });

const stored = $('Load The Whole Index').all();
const scored = [];
for (const item of stored) {
  const r = item.json || {};
  if (!r.vec) { continue; }
  const v = String(r.vec).split(',');
  // A vector of the wrong length is an index built at a different
  // `dimensions`. Skipping it quietly would report that the docs cover
  // nothing, so the count is checked below and turned into a real error.
  if (v.length !== q.length) { continue; }
  let dot = 0;
  for (let i = 0; i < q.length; i++) { dot += q[i] * Number(v[i]); }
  scored.push({ score: dot, url: String(r.url || ''), title: String(r.title || ''), text: String(r.text || '') });
}

if (stored.length && !scored.length) {
  throw new Error('The index holds ' + stored.length + ' passages and none of them are ' + q.length + '-dimensional. Re-run the indexing branch after changing dimensions.');
}

scored.sort(function (a, b) { return b.score - a.score; });
const top = scored.slice(0, topK);
const best = top.length ? top[0].score : 0;

const context = top.map(function (p, i) {
  return '[' + (i + 1) + '] ' + p.title + ' (' + p.url + ')\n' + p.text;
}).join('\n\n');

const sources = [];
for (const p of top) {
  if (sources.indexOf(p.url) < 0) { sources.push(p.url); }
}

return [{ json: {
  question: asked.question,
  subject: asked.subject,
  reply_to: asked.reply_to,
  thread_id: asked.thread_id,
  asked_on: asked.asked_on,
  covered: top.length > 0 && best >= floor,
  best_score: Math.round(best * 1000) / 1000,
  indexed_passages: stored.length,
  sources: sources,
  context: context,
  note: stored.length ? '' : 'the index is empty - run the indexing branch first',
}}];

parameters.text:
=You are checking a drafted support reply against the passages it was supposed to be built from. You did not write it and you have no stake in it.

PASSAGES
{{ $('Find The Closest Passages').first().json.context }}

DRAFT
{{ $json.text }}

Go claim by claim. A claim is supported only when a passage states it. A claim that is merely plausible, or true of most products, is unsupported. Any number, limit, price or timeframe that no passage states is unsupported. If the whole draft is NOT_IN_DOCS, the verdict is supported.

Return JSON only: {"verdict": "supported" or "unsupported", "unsupported": ["the exact claim", "..."]}

parameters.jsCode:
// The draft and its audit both arrive as text. Both are parsed defensively - a
// model wrapping JSON in a sentence of prose is the normal case, not the
// exception - and the audit wins: a reply that cannot be traced back to a
// passage does not go out, whatever the draft says about itself.
//
// single-item input: one question per run.
const found = $('Find The Closest Passages').first().json;
const draftRaw = String(($('Draft The Answer From The Passages').first().json || {}).text || '');
const auditRaw = String(($input.first().json || {}).text || '');

function parse(raw) {
  const s = raw.indexOf('{');
  const e = raw.lastIndexOf('}');
  if (s < 0 || e <= s) { return null; }
  try { return JSON.parse(raw.slice(s, e + 1)); } catch (err) { return null; }
}

const draft = parse(draftRaw) || {};
const audit = parse(auditRaw) || {};

let answer = String(draft.answer || '').trim();
if (!answer && draftRaw.indexOf('{') < 0) { answer = draftRaw.trim(); }

const refused = !answer || /NOT_IN_DOCS/i.test(answer) || /NOT_IN_DOCS/i.test(draftRaw);

// The verdict comes back off its two-word list often enough to plan for:
// "Supported", "partially supported" and a bare "no" have all appeared where
// one of two words was asked for. Anything that is not exactly supported is
// treated as not supported.
const verdict = String(audit.verdict || '').toLowerCase().trim();
const unsupported = (audit.unsupported || [])
  .map(function (u) { return String(u).slice(0, 200); })
  .filter(Boolean);

const ok = !refused && verdict === 'supported' && unsupported.length === 0;
const sources = (found.sources || []).slice(0, 4);
const subject = /^re:/i.test(String(found.subject || '')) ? found.subject : 'Re: ' + found.subject;

let reason = '';
if (refused) {
  reason = 'the model would not answer from these passages';
} else if (unsupported.length) {
  reason = unsupported.join(' | ');
} else if (!ok) {
  reason = 'the audit returned "' + (verdict || 'nothing') + '" rather than a supported verdict';
}

return [{ json: Object.assign({}, found, {
  ok: ok,
  escalate: !ok,
  answer: answer,
  unsupported: unsupported,
  reason: reason,
  reply_subject: subject,
  reply_body: answer + (sources.length ? '\n\nWhere this comes from:\n' + sources.join('\n') : ''),
})}];

// Both refusals arrive here: the one where nothing in the index came close
// enough to be worth a model call, and the one where the draft made a claim the
// passages do not support. Neither reaches the customer.
//
// Nothing is read by node name on purpose - one of the two upstream nodes did
// not run, and reading an unexecuted node throws.
//
// single-item input: one question per run.
const j = $input.first().json || {};
const cfg = $('Answer Settings').first().json;

const why = j.escalate
  ? 'The draft was not backed by the docs: ' + (j.reason || 'an unsupported claim')
  : 'Nothing in the docs came close. Best passage scored ' + j.best_score + ' against a floor of ' + cfg.min_score + (j.note ? ' (' + j.note + ')' : '');

const quoted = String(j.question || '').split('\n').slice(0, 6).join('\n> ').slice(0, 900);

const lines = [
  '*A support question your docs do not answer*',
  '',
  '*From* ' + (j.reply_to || 'unknown') + '   *Subject* ' + (j.subject || ''),
  '',
  '> ' + quoted,
  '',
  why,
];
if ((j.sources || []).length) {
  lines.push('', 'Closest pages: ' + j.sources.slice(0, 3).join('  '));
}

return [{ json: {
  message: lines.join('\n'),
  question: String(j.question || '').slice(0, 500),
  status: j.escalate ? 'unsupported' : 'not covered',
  best_score: j.best_score,
  note: why.slice(0, 300),
  asked_on: j.asked_on || '',
}}];
